begin;select plan(13);select ok(to_regclass('public.reports')is not null,'reports');select ok(to_regclass('public.moderation_actions')is not null,'actions');select ok(to_regclass('public.duplicate_identity_reviews')is not null,'duplicates');select ok(to_regclass('private.player_identity_aliases')is not null,'aliases');select has_function('public','create_report',array['text','uuid','text','text','uuid[]','uuid']);select has_function('public','review_report',array['uuid','bigint','text','text','uuid']);select has_function('public','apply_moderation_action',array['uuid','text','uuid','text','text','timestamptz','uuid']);select has_function('public','merge_duplicate_players',array['uuid','uuid','text','uuid']);select has_function('public','adjust_player_trust_score',array['uuid','text','numeric','uuid','uuid']);select ok(exists(select 1 from pg_proc where oid=to_regprocedure('public.review_report(uuid,bigint,text,text,uuid)')and prosrc like'%require_platform_admin%'),'admin checked');select ok(not has_table_privilege('authenticated','public.moderation_actions','INSERT'),'no direct writes');select ok(exists(select 1 from pg_indexes where indexname='duplicate_review_open_pair_idx'),'one open pair');select ok(exists(select 1 from pg_proc where oid=to_regprocedure('public.apply_moderation_action(uuid,text,uuid,text,text,timestamptz,uuid)')and prosrc like'%USE_DISPUTE_WORKFLOW%'),'results excluded');select*from finish();rollback;
